#include <stdint.h>
typedef struct {uint64_t hi, lo;} u128;
static u128 mul(u128 x, u128 y){
  u128 z={0,0};
  for(int i=0;i<128;i++){
    uint64_t bit = i<64 ? (y.hi>>(63-i))&1 : (y.lo>>(127-i))&1;
    if(bit){z.hi^=x.hi; z.lo^=x.lo;}
    uint64_t lsb=x.lo&1;
    x.lo=(x.lo>>1)|(x.hi<<63); x.hi>>=1;
    if(lsb) x.hi^=0xE100000000000000ULL;
  }
  return z;
}
static u128 ld(const unsigned char*p){u128 r={0,0};for(int i=0;i<8;i++){r.hi=(r.hi<<8)|p[i];r.lo=(r.lo<<8)|p[8+i];}return r;}
static void st(unsigned char*p,u128 r){for(int i=7;i>=0;i--){p[i]=r.hi&0xff;r.hi>>=8;p[8+i]=r.lo&0xff;r.lo>>=8;}}
static u128 pw(u128 x, unsigned __int128 e){u128 r={1ULL<<63,0};while(e){if(e&1)r=mul(r,x);x=mul(x,x);e>>=1;}return r;}
static u128 X(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
/* combine: tags[i] = EJ0 ^ GHASH(C_i || len(0,n_i)); aadtag likewise for aad (if al>0) */
void combine(const unsigned char*Hb,const unsigned char*Eb,int nseg,const unsigned char*tags,const uint64_t*lens,
             const unsigned char*aadtag,uint64_t al,unsigned char*outtag){
  u128 H=ld(Hb),E=ld(Eb);
  unsigned __int128 e=~(unsigned __int128)0; e-=1;
  u128 Hinv=pw(H,e);
  u128 S={0,0}; uint64_t L=0;
  if(al){u128 t=X(ld(aadtag),E); u128 lb={al*8,0}; S=mul(X(t,mul(lb,H)),Hinv);}
  for(int i=0;i<nseg;i++){
    uint64_t n=lens[i]; L+=n;
    u128 v=X(ld(tags+16*i),E); u128 lb={0,n*8};
    u128 sc=mul(X(v,mul(lb,H)),Hinv);
    S=X(mul(S,pw(H,(n+15)/16)),sc);
  }
  u128 lb={al*8,L*8};
  S=mul(X(S,lb),H);
  st(outtag,X(S,E));
}
EOF
